style.css:
@-moz-document domain("roblox.com") {
/* ==== BACKGROUND IMAGE (site-wide) ==== */
  html, body {
    background: transparent !important;
  }

  body {
    position: relative;
    min-height: 100vh;
  }

  body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -2;
    background-image: url("https://cdn.wallpapersafari.com/65/87/T8kPwY.jpg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    filter: saturate(1.05) contrast(1.02);
    pointer-events: none;
  }

  body::after {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    background: rgba(0,0,0,0.35);
    pointer-events: none;
  }

  /* Make common page containers transparent so the bg shows through */
  #wrap-viewport, #viewport,
  .rbx-viewport, .container-main, .container,
  main, .content, .page-content {
    background: transparent !important;
  }

  /* ==== OPTIONAL: Hide obvious blog elements (safe CSS only) ==== */
  .blog-list,
  .blog-item,
  .rbx-blog,
  .rbx-updates,
  .sidebar-blog,
  .side-blog,
  div[id*="Blog"],
  div[class*="Blog"],
  div[class*="blog"] {
    display: none !important;
    visibility: hidden !important;
  }

  /* ==== Glassy top bar ==== */
  #navigation,
  #header,
  .header,
  nav,
  .topbar,
  .rbx-navbar,
  .navbar,
  .site-header,
  .navbar-fixed-top,
  #topnav,
  div[class*="Topbar" ],
  div[class*="topbar" ] {
    background: rgba(255,255,255,0.15) !important;
    -webkit-backdrop-filter: blur(6px) saturate(1.05) !important;
    backdrop-filter: blur(6px) saturate(1.05) !important;
  }

  /* ==== Glassy sidebars ==== */
  .sidebar,
  .rbx-sidebar,
  .site-left-col,
  .site-right-col,
  div[class*="sidebar" ],
  aside {
    background: rgba(255,255,255,0.15) !important;
    -webkit-backdrop-filter: blur(6px) !important;
    backdrop-filter: blur(6px) !important;
  }

  /* ==== Keep popups above ==== */
  div[role="dialog"],
  .modal,
  .popover,
  .dropdown-menu,
  .menu {
    z-index: 2000 !important;
  }

  /* Readability */
  a, button, .btn, .text-link {
    color: #fff !important;
  }
}
